    const len = big ? 20 : r.int(1, 7);
    if (r.bool(0.4)) {
      // build something close to valid, then maybe break one character
      const sign = () => r.pick(["", "", "+", "-"]);
      const digits = k => r.str(k, "0123456789");
      let m = sign();
      const shape = r.int(0, 3);
      if (shape === 0) m += digits(r.int(1, 3));
      else if (shape === 1) m += digits(r.int(1, 3)) + ".";
      else if (shape === 2) m += "." + digits(r.int(1, 3));
      else m += digits(r.int(1, 2)) + "." + digits(r.int(1, 2));
      if (r.bool(0.5)) m += r.pick(["e", "E"]) + sign() + digits(r.int(0, 2));
      if (r.bool(0.3)) { const i = r.int(0, m.length - 1); m = m.slice(0, i) + r.pick([".", "e", "+", "-", "x", "1"]) + m.slice(i + 1); }
      return [m.slice(0, 20)];
    }
    return [r.str(len, "0123456789..++--eEa")];
  }

