function isWellFormedNumber(s: string): boolean {
  let digit = false, dot = false, exp = false;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c >= "0" && c <= "9") {
      digit = true;
    } else if (c === "+" || c === "-") {
      if (i > 0 && s[i - 1] !== "e" && s[i - 1] !== "E") return false;
    } else if (c === ".") {
      if (dot || exp) return false;
      dot = true;
    } else if (c === "e" || c === "E") {
      if (exp || !digit) return false;
      exp = true;
      digit = false; // the exponent needs its own digits
    } else {
      return false;
    }
  }
  return digit;
}

