    def isWellFormedNumber(self, s: str) -> bool:
        digit = dot = exp = False
        for i, c in enumerate(s):
            if c.isdigit():
                digit = True
            elif c in "+-":
                if i > 0 and s[i - 1] not in "eE":
                    return False
            elif c == ".":
                if dot or exp:
                    return False
                dot = True
            elif c in "eE":
                if exp or not digit:
                    return False
                exp = True
                digit = False  # the exponent needs its own digits
            else:
                return False
        return digit

