function isWellFormedNumber(s: string): boolean {
  // sign, then digits with an optional dot (a digit on at least one side), then an optional exponent
  return /^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/.test(s);
}

